def compare(game, guess):
    """Determine if a person correctly guessed match results.
    Arrays of identical length with game scores and guesses are provided. The arrays have elements such that;
    each index represents a match, showing final results and predicted scores, respectively. 
    Return an array of the same length denoting how far off each guess was. If they have guessed correctly,
    the value is 0, and if not, the value is the absolute difference between the guess and the score.
    """

    differences = []

    for game_score, guess_score in zip(game, guess):
        differences.append(abs(game_score - guess_score))

    return differences
